# //CODE

const int R1 = 1;

const int Y1= 2;

const int G1 = 3;

const int R2 = 5; 

const int Y2= 6;

const int G2 = 7;

const int R3 = 8; 

const int Y3= 9;

const int G3 = 10;

const int R4 = 11; 

const int Y4= 12;

const int G4 = 13;

void setup()

{

  

  pinMode(R1, OUTPUT);

  pinMode(G1, OUTPUT);

  pinMode(Y1, OUTPUT);

  pinMode(R2, OUTPUT);

  pinMode(Y2, OUTPUT);

  pinMode(G2, OUTPUT);

  pinMode(R3, OUTPUT);

  pinMode(G3, OUTPUT);

  pinMode(Y3, OUTPUT);

  pinMode(R4, OUTPUT);

  pinMode(Y4, OUTPUT);

  pinMode(G4, OUTPUT);

}

void loop()

{

  digitalWrite(R1, LOW);

  digitalWrite(Y1, LOW);

  digitalWrite(G1, HIGH);

  digitalWrite(R2, HIGH);

  digitalWrite(Y2, LOW);

  digitalWrite(G2, LOW);

  digitalWrite(R3, LOW);

  digitalWrite(Y3, LOW);

  digitalWrite(G3, HIGH);

  digitalWrite(R4, HIGH);

  digitalWrite(Y4, LOW);

  digitalWrite(G4, LOW);

  delay(8000);

  digitalWrite(R1, LOW);

  digitalWrite(Y1, HIGH);

  digitalWrite(G1, LOW);

  digitalWrite(R2, LOW);

  digitalWrite(Y2, HIGH);

  digitalWrite(G2, LOW);

  digitalWrite(R3, LOW);

  digitalWrite(Y3, HIGH);

  digitalWrite(G3, LOW);

  digitalWrite(R4, LOW);

  digitalWrite(Y4, HIGH);

  digitalWrite(G4, LOW);

  delay(3000);

  digitalWrite(R1,HIGH);

  digitalWrite(Y1, LOW);

  digitalWrite(G1, LOW);

  digitalWrite(R2, LOW);

  digitalWrite(Y2, LOW);

  digitalWrite(G2, HIGH);

  digitalWrite(R3, HIGH);

  digitalWrite(Y3, LOW);

  digitalWrite(G3, LOW);

  digitalWrite(R4, LOW);

  digitalWrite(Y4, LOW);

  digitalWrite(G4,HIGH);

  delay(8000);

  digitalWrite(R1, LOW);

  digitalWrite(Y1, HIGH);

  digitalWrite(G1, LOW);

  digitalWrite(R2, LOW);

  digitalWrite(Y2, HIGH);

  digitalWrite(G2, LOW);

  digitalWrite(R3, LOW);

  digitalWrite(Y3, HIGH);

  digitalWrite(G3, LOW);

  digitalWrite(R4, LOW);

  digitalWrite(Y4, HIGH);

